/* ===== Dark theme ===== */
/* Tailwind v4 utilities reference these CSS variables, so remapping them
   in `.dark` re-themes every surface, border, and text color at once. */
.dark {
  color-scheme: dark;

  --color-white: #fff;

  --color-slate-50: #0d131d;
  --color-slate-100: #151c27;
  --color-slate-200: #1c2531;
  --color-slate-300: #253040;
  --color-slate-400: #90a1b8;
  --color-slate-500: #a6b4c7;
  --color-slate-600: #bdc9da;
  --color-slate-700: #d1da2e;
  --color-slate-800: #e2e8f0;
  --color-slate-900: #eef3f8;
  --color-slate-950: #f8fafc;

  --color-sky-50: #0c1b2e;
  --color-sky-100: #123047;
  --color-sky-200: #1a4567;
  --color-sky-500: #38bdf8;
  --color-sky-600: #0ea5e9;
  --color-sky-700: #38bdf8;

  --color-emerald-50: #06382b;
  --color-emerald-100: #0a5340;
  --color-emerald-200: #10634c;
  --color-emerald-400: #34d399;
  --color-emerald-600: #34d399;
  --color-emerald-700: #6ee7b7;
  --color-emerald-800: #a9f1cd;

  --color-amber-50: #3a2d0d;
  --color-amber-100: #45360a;
  --color-amber-300: #fcd34d;
  --color-amber-500: #fbbf24;
  --color-amber-600: #fbbf24;
  --color-amber-700: #fcd34d;

  --color-red-50: #3a1616;
  --color-red-100: #4a2020;
  --color-red-500: #fb7185;
  --color-red-600: #f87171;
  --color-red-700: #fca5a5;
}

.dark body {
  background: #0d1220;
}

/* White text must stay readable on the (unchanged) coloured buttons. */
.dark .text-white {
  color: #ffffff;
}

.dark .ring-white {
  --tw-ring-color: #ffffff;
}

/* Keep genuinely-dark surfaces dark (chat code blocks, toast fallbacks). */
.dark .bg-slate-700,
.dark .bg-slate-800,
.dark .bg-slate-900,
.dark .bg-slate-950 {
  background-color: #101722;
}
.dark .chat-bubble-bot pre {
  background-color: #0b101a;
  color: #dce4ee;
}
.dark .chat-bubble-bot pre code {
  color: #dce4ee;
}

/* MUI Tabs inherit the default dark text in light theme; re-colour for dark. */
.dark .MuiTab-root {
  color: #bdc9da;
}
.dark .MuiTab-root.Mui-selected {
  color: #7dd3fc;
}

/* The floating navbar uses explicit light/active colours. */
.dark .floatnav-pill {
  border-color: color-mix(in oklab, var(--color-slate-200) 60%, transparent);
  background-color: rgba(21, 29, 41, 0.9);
}
.dark .floatnav-item {
  color: var(--color-slate-500);
}
.dark .floatnav-item-active,
.dark .floatnav-item-theme:hover {
  background-color: var(--color-sky-600);
  color: #ffffff;
}

