const { DatabaseSync } = require('node:sqlite');
const fs = require('node:fs');
const path = require('node:path');

const DB = path.join(process.env.HOME, '.local/share/opencode/opencode.db');
const WORKTREE = '/Users/rayhan/Desktop/Code projects/Openglimpse';
const OUT = '/Users/rayhan/Desktop/Code projects/Openglimpse/ai/rayhan/ai-logs';

const db = new DatabaseSync(DB, { readOnly: true });

function safe(s) {
  return String(s || '').replace(/\t/g, ' ');
}
function sanitizeName(title) {
  return title.replace(/[^a-zA-Z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60) || 'session';
}

const rows = db.prepare(`
  SELECT s.id, s.title, s.parent_id, s.agent, s.model, s.cost,
         s.tokens_input, s.tokens_output, s.tokens_reasoning, s.tokens_cache_read,
         datetime(s.time_created/1000,'unixepoch') AS created,
         datetime(s.time_updated/1000,'unixepoch') AS updated,
         s.time_created AS t
  FROM session s JOIN project p ON p.id = s.project_id
  WHERE p.worktree = ? AND s.parent_id IS NULL
  ORDER BY s.time_created
`).all(WORKTREE);

function getMessages(sessionId) {
  return db.prepare(`
    SELECT m.id, m.role, m.time_created AS t, m.data AS mdata
    FROM message m WHERE m.session_id = ? ORDER BY m.time_created, m.id
  `).all(sessionId);
}

function getParts(messageId) {
  return db.prepare(`
    SELECT p.time_created, p.data FROM part p WHERE p.message_id = ? ORDER BY p.time_created, p.id
  `).all(messageId);
}

function clean(text) {
  return String(text ?? '').replace(/\u0000/g, '');
}

function renderMessage(msg) {
  const parts = getParts(msg.id);
  const out = [];
  for (const p of parts) {
    let d;
    try { d = JSON.parse(p.data); } catch { continue; }
    if (d.type === 'reasoning') continue;
    if (d.type === 'text') {
      out.push(clean(d.text));
    } else if (d.type === 'tool') {
      const call = d.state?.input || {};
      const keys = ['command', 'filePath', 'pattern', 'url'];
      const firstKey = keys.find((k) => k in call);
      out.push(`[tool:${d.tool}] ${firstKey ? `${firstKey}: ${String(call[firstKey]).slice(0, 300)}` : ''}`);
    } else if (d.type === 'error') {
      out.push(`[error] ${clean(d.error || d.message || '')}`);
    }
  }
  if (msg.role === 'user' && msg.mdata) {
    try {
      const md = JSON.parse(msg.mdata);
      if (md.summary?.diffs?.length) out.push(`[diff stats: ${md.summary.diffs.length} files, ${md.summary.additions}+/${md.summary.deletions}-]`);
    } catch {}
  }
  return out.filter(Boolean);
}

let fileIdx = 0;
for (const s of sessions) {
  fileIdx++;
  const messages = getMessages(s.id);
  const blocks = [];
  for (const m of messages) {
    const role = m.role === 'user' ? '**User:**' : '**Assistant:**';
    const body = renderMessage(m.id).join('\n\n');
    if (!body) continue;
    const header = `${role} (${new Date(m.t * 1000).toISOString()})`;
    blocks.push(`${header}\n\n${body}`);
  }
  const content = [
    `# ${s.title}`,
    '',
    `- **Session ID:** \`${s.id}\``,
    `- **Model:** ${s.model}`,
    `- **Created:** ${s.created}  **Updated:** ${s.updated}`,
    `- **Tokens:** ${s.tokens_input} in / ${s.tokens_output} out / ${s.tokens_reasoning} reasoning / ${s.tokens_cache_read} cache-read | **Cost:** $${Number(s.cost).toFixed(4)}`,
    '',
    '---',
    '',
    ...blocks,
    '',
  ].join('\n');

  const fname = `${String(fileIdx).padStart(3, '0')}_${sanitizeName(s.title)}.md`;
  fs.writeFileSync(path.join(OUT, fname), content);
  console.log('wrote', fname, `(${blocks.length} message blocks)`);
}

console.log(`\nTotal: ${sessions.length} sessions extracted to ${OUT}`);

